# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, offset=1):
    return [v + offset for v in xs]

# region: emit
def emit(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: render
def render(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: gather
def gather(summary, bar=3):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return gather(render(emit(fold(intake(raw)))))

